from collections import deque

def kin_distance(parents: dict, a: str, b: str):
    def ancestor_distances(start: str) -> dict:
        distances = {start: 0}
        queue = deque([start])

        while queue:
            person = queue.popleft()
            for parent in parents.get(person, []):
                if parent not in distances:
                    distances[parent] = distances[person] + 1
                    queue.append(parent)

        return distances

    dist_a = ancestor_distances(a)
    dist_b = ancestor_distances(b)

    best_sum = None
    best_da = None

    for ancestor, da in dist_a.items():
        db = dist_b.get(ancestor)
        if db is None:
            continue

        total = da + db

        if (
            best_sum is None
            or total < best_sum
            or (total == best_sum and da < best_da)
        ):
            best_sum = total
            best_da = da

    if best_sum is None:
        return None

    return (best_da, best_sum - best_da)
