def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    orders: dict[str, dict] = {}
    totals: dict[str, int] = {}
    first_buy_ts: dict[str, int] = {}

    for _, event in sorted(enumerate(events), key=lambda pair: (pair[1]["ts"], pair[0])):
        order_id = event["order"]
        event_type = event["type"]

        if event_type == "buy":
            if order_id in orders:
                continue

            customer = event["customer"]
            amount = event["cents"]

            orders[order_id] = {
                "customer": customer,
                "amount": amount,
                "cancelled": False,
            }

            totals[customer] = totals.get(customer, 0) + amount

            if customer not in first_buy_ts:
                first_buy_ts[customer] = event["ts"]

        elif event_type == "refund":
            order = orders.get(order_id)
            if order is None or order["cancelled"]:
                continue

            new_amount = max(0, order["amount"] - event["cents"])

            if new_amount != order["amount"]:
                customer = order["customer"]
                order["amount"] = new_amount
                totals[customer] += new_amount - order["amount"]

        elif event_type == "cancel":
            order = orders.get(order_id)
            if order is None:
                continue

            if not order["cancelled"]:
                customer = order["customer"]
                amount = order["amount"]

                if amount:
                    totals[customer] -= amount

                order["amount"] = 0
                order["cancelled"] = True

    ranked = [
        (total, customer)
        for customer, total in totals.items()
        if total > 0
    ]

    ranked.sort(key=lambda item: (-item[0], first_buy_ts[item[1]], item[1]))

    return [(customer, total) for total, customer in ranked[:k]]
